L1: /**
L2:  * SQLite driver adapter.
L3:  *
L4:  * opencode runs on Bun, where `bun:sqlite` is built in; tests and other Node
L5:  * runtimes use `node:sqlite` (Node >= 22.5). Both are stdlib, so the store
L6:  * carries zero npm dependencies. This is the ONLY module that touches a runtime
L7:  * SQLite binding, and it does so exclusively through dynamic `import()` behind
L8:  * variable specifiers so `src/` stays free of Node/Bun types (see AGENTS.md) and
L9:  * so the bundler never tries to inline a native driver. Every open failure is
L10:  * swallowed: {@link openSqlite} returns `null` (a missing driver degrades the
L11:  * plugin to ephemeral mode rather than throwing), and {@link openSqliteReadOnly}
L12:  * returns `{ ok: false, reason }`.
L13:  */
L14: export type SqlValue = string | number | bigint | null | Uint8Array;
L15: export type Row = Record<string, SqlValue>;
L16: /**
L17:  * Minimal, driver-neutral surface over a SQLite connection.
L18:  *
L19:  * `run` returns both `changes` and `lastInsertRowid` (a deliberate, minimal
L20:  * extension of the sketch's `{ changes }`): the per-session FTS mirror needs the
L21:  * rowid assigned to each freshly inserted `part_text` row, and both drivers
L22:  * report it natively. `get` normalizes the drivers' "no row" sentinel (bun
L23:  * returns `null`, node returns `undefined`) to `undefined`.
L24:  */
L25: export type SqliteDb = {
L26:     exec(sql: string): void;
L27:     run(sql: string, params?: SqlValue[]): {
L28:         changes: number;
L29:         lastInsertRowid: number;
L30:     };
L31:     get(sql: string, params?: SqlValue[]): Row | undefined;
L32:     all(sql: string, params?: SqlValue[]): Row[];
L33:     /** BEGIN IMMEDIATE / COMMIT, rolling back (best-effort) if `fn` throws. */
L34:     tx<T>(fn: () => T): T;
L35:     close(): void;
L36: };
L37: /**
L38:  * Open a SQLite database, preferring `bun:sqlite` when running under Bun and
L39:  * falling back to `node:sqlite`. Returns `null` on any import or open failure so
L40:  * the caller can degrade rather than crash.
L41:  */
L42: export declare function openSqlite(path: string): Promise<SqliteDb | null>;
L43: /** A read-only handle: statements that return rows, and close. No `exec`,
L44:  *  `run` or `tx`, in the type or on the object, so a write cannot even be
L45:  *  attempted by accident (and `query_only` refuses one sent through `get`). */
